UPDATE `videos` SET `description_doc` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Join Brendan O''Brien for a hands-on introduction to "},{"type":"text","text":"Iroh","marks":[{"type":"bold"}]},{"type":"text","text":", the peer-to-peer networking library that makes direct device-to-device connections simple, secure, and reliable."}]},{"type":"paragraph","content":[{"type":"text","text":"In this live session, we explore:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What Iroh is and the problems it solves"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How its networking model works"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Building peer-to-peer applications without the usual networking headaches"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Live demos and practical examples"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Best practices, tips, and audience Q&A"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Whether you''re building distributed systems, local-first applications, multiplayer experiences, or developer tools, Iroh offers a modern approach to authenticated, encrypted connectivity that works across networks."}]},{"type":"paragraph","content":[{"type":"text","text":"🔗 Learn more:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rawkode Academy: "},{"type":"text","text":"https://rawkode.academy","marks":[{"type":"link","attrs":{"href":"https://rawkode.academy","target":null,"rel":null,"class":null,"title":null}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Iroh Documentation: "},{"type":"text","text":"https://docs.iroh.computer","marks":[{"type":"link","attrs":{"href":"https://docs.iroh.computer","target":null,"rel":null,"class":null,"title":null}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Iroh: "},{"type":"text","text":"https://www.iroh.computer","marks":[{"type":"link","attrs":{"href":"https://www.iroh.computer","target":null,"rel":null,"class":null,"title":null}}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Subscribe for more deep dives into cloud native, distributed systems, Rust, Kubernetes, and modern infrastructure."}]},{"type":"paragraph","content":[{"type":"text","text":"#Iroh #RustLang #P2P #DistributedSystems #Networking #CloudNative #Rawkode"}]}]}' WHERE `id` = 'ki0qbn121pdjly5f5vtvii1m';
UPDATE `videos` SET `description_doc` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Git has dominated the version control landscape for over a decade, but does that mean we''ve reached the end of history for VCS? Join us for a deep dive into Jujutsu (jj), a Git-compatible version control system that might change the way you think about source control."}]}]}' WHERE `id` = 'm7az25q3ide58725jigj9a5m';
UPDATE `videos` SET `description_doc` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Join Amy Chen for a hands-on introduction to "},{"type":"text","text":"Kueue","marks":[{"type":"bold"}]},{"type":"text","text":", the Kubernetes-native job queueing system for batch, HPC, and AI/ML workloads."}]},{"type":"paragraph","content":[{"type":"text","text":"Kubernetes knows how to schedule Pods, but running large collections of resource-intensive jobs introduces another set of challenges. Which workloads should start first? How should limited GPUs be shared between teams? What happens when demand exceeds cluster capacity?"}]},{"type":"paragraph","content":[{"type":"text","text":"Kueue adds workload admission, queueing, quotas, priorities, fair sharing, and preemption without replacing the Kubernetes scheduler."}]},{"type":"paragraph","content":[{"type":"text","text":"In this live session, we explore:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What Kueue is and where it fits in the Kubernetes scheduling stack"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The difference between scheduling and workload admission"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"LocalQueues, ClusterQueues, ResourceFlavors, and Workloads"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Managing CPU, memory, GPU, and other resource quotas"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sharing cluster capacity across teams and namespaces"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Priorities, fair sharing, borrowing, and preemption"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Installing and configuring Kueue"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Submitting and observing queued jobs"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Practical considerations for batch, HPC, and AI/ML platforms"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Live demonstrations and audience questions"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Amy will take us beyond the architecture and show how Kueue behaves inside a real Kubernetes environment."}]},{"type":"paragraph","content":[{"type":"text","text":"Whether you operate shared GPU clusters, machine-learning platforms, research infrastructure, CI systems, or large-scale batch workloads, this session will provide a practical foundation for managing queued work with Kubernetes."}]}]}' WHERE `id` = 'elpqrlouhe220jyf5tqr65vm';
UPDATE `videos` SET `description_doc` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Join Peter Mbanugo for a hands-on introduction to "},{"type":"text","text":"Odin","marks":[{"type":"bold"}]},{"type":"text","text":", a modern systems programming language designed for simplicity, performance, and practical software development."}]},{"type":"paragraph","content":[{"type":"text","text":"In this live session, we explore:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What Odin is and the problems it aims to solve"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Odin’s approach to types, memory, packages, and error handling"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How Odin compares with languages such as C, C++, Rust, and Zig"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Setting up the Odin toolchain and creating a new project"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Building a practical application live"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Common patterns, useful libraries, and developer tooling"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Audience questions and live experimentation"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Whether you are interested in systems programming, game development, graphics, performance-sensitive applications, or exploring alternatives to C and C++, this session will give you a practical foundation for working with Odin."}]},{"type":"paragraph","content":[{"type":"text","text":"🔗 Learn more:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rawkode Academy: "},{"type":"text","text":"https://rawkode.academy","marks":[{"type":"link","attrs":{"href":"https://rawkode.academy","target":null,"rel":null,"class":null,"title":null}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Odin: "},{"type":"text","text":"https://odin-lang.org","marks":[{"type":"link","attrs":{"href":"https://odin-lang.org","target":null,"rel":null,"class":null,"title":null}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Odin Documentation: "},{"type":"text","text":"https://odin-lang.org/docs","marks":[{"type":"link","attrs":{"href":"https://odin-lang.org/docs","target":null,"rel":null,"class":null,"title":null}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Odin GitHub: "},{"type":"text","text":"https://github.com/odin-lang/Odin","marks":[{"type":"link","attrs":{"href":"https://github.com/odin-lang/Odin","target":null,"rel":null,"class":null,"title":null}}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Subscribe for more hands-on sessions covering programming languages, cloud native technologies, distributed systems, Kubernetes, Rust, WebAssembly, and modern infrastructure."}]},{"type":"paragraph","content":[{"type":"text","text":"#OdinLang #SystemsProgramming #ProgrammingLanguages #GameDevelopment #SoftwareDevelopment #RawkodeAcademy"}]}]}' WHERE `id` = 'nlnsodk2e7tnmwfychc7400m';
