UPDATE `videos` SET `description_doc` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Four tools for Kubernetes day-two security: kube-bench for CIS hygiene, kube-hunter for red-team probing, Sonobuoy for CNCF conformance, and Syft plus Grype for SBOMs and CVEs. Demo runs them by hand, then automates via Spectro Cloud Palette."}]}]}' WHERE `id` = 'sgs7tm99rldi3ev42yzacukd';
UPDATE `videos` SET `description_doc` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"MinIO put their community edition into maintenance mode. We walk through how they got here: silent AGPL relicensing in 2019 and 2021, the Weka license-revocation stunt, gutting the May 2025 community console, and pushing a $96K paywall for features that used to be free."}]}]}' WHERE `id` = 'xqw6ifttca4q4sdninffrwml';
UPDATE `videos` SET `description_doc` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Install the ngrok Kubernetes Operator with Helm, then expose a workload using an AgentEndpoint and TrafficPolicy. Add OIDC auth via Zitadel, rate limiting, and a custom 429 page, all without load balancers or port forwarding."}]}]}' WHERE `id` = 'vsyhv7s6wvz4p9fuq507u28g';
UPDATE `videos` SET `description_doc` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Building a marketing page for the Klustered relaunch with Heroku Vibes. Covers AI-assisted development, deployment to Heroku, wiring up interactive features, then debugging the rough edges before recapping what''s next for the show."}]}]}' WHERE `id` = 'mbi5212lbf8b3yvidkeamkkm';
UPDATE `videos` SET `description_doc` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Author GitHub Actions workflows in CUE instead of YAML. Walk through cue vet, import, and export, pull workflow definitions from the CUE Central Registry, pin actions to SHAs, and wire in a Dagger install step."}]}]}' WHERE `id` = 'eihdoemxfyzm33pxzcix5ci5';
UPDATE `videos` SET `description_doc` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In this video, learn how to effectively use ngrok to debug and troubleshoot your applications in production. We''ll explore a practical use case where production traffic is routed to a local machine for debugging using ngrok traffic policies."}]}]}' WHERE `id` = 'z7fzq9jqcn0m0noy4qkmevjq';
UPDATE `videos` SET `description_doc` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"BGP routes the internet like Google Maps, but running your own POPs is hard. ngrok''s global load balancer spans 8 POPs with automatic failover, demoed here with two Deno apps tunnelled from EU and US."}]}]}' WHERE `id` = 'h0e270cxlhdgnr6x20mcno3d';
UPDATE `videos` SET `description_doc` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A look at Hadron, the minimal Linux distribution from the Kairos project. Built from upstream components (musl libc, systemd, vanilla kernels) with no base-OS package manager, designed as a lean foundation for immutable, image-based cloud and edge systems."}]}]}' WHERE `id` = 'hxjai2mhvplhc4rl3c7dq2eh';
